        /// <param name="limit">Max neighbours per page (optional)</param>
        /// <param name="cursor">Continuation token from &#x60;page.nextCursor&#x60; (optional)</param>
        /// <param name="count">Also return the subject&#39;s visible edge total in &#x60;page.totalSize&#x60;. Cannot be combined with &#x60;minFacts&#x60;. (optional)</param>
        /// <param name="cancellationToken">Cancellation Token to cancel the request.</param>
        /// <returns><see cref="Task"/>&lt;<see cref="IEntityNeighbourhoodApiResponse"/>&gt;</returns>
